Here's a complete self-contained HTML file with a spiral galaxy canvas animation:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Spiral Galaxy</title>
<style>
  html, body { margin: 0; padding: 0; overflow: hidden; background: #000; }
  canvas { display: block; }
</style>
</head>
<body>
<canvas id="galaxy"></canvas>
<script>
(function() {
  const canvas = document.getElementById('galaxy');
  const ctx = canvas.getContext('2d');
  let W, H, cx, cy;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
    cx = W / 2;
    cy = H / 2;
  }
  window.addEventListener('resize', resize);
  resize();

  // ---- Galaxy parameters ----
  const NUM_STARS = 700;
  const NUM_ARMS = 2;
  const ARM_TWIST = 4.5;      // how tightly arms wind
  const CORE_RADIUS = 18;
  const GALAXY_RADIUS = Math.min(W, H) * 0.46;

  // Star data arrays
  const baseRadius = new Float32Array(NUM_STARS);
  const baseAngle  = new Float32Array(NUM_STARS);
  const size       = new Float32Array(NUM_STARS);
  const colorR     = new Float32Array(NUM_STARS);
  const colorG     = new Float32Array(NUM_STARS);
  const colorB     = new Float32Array(NUM_STARS);
  const twinklePhase = new Float32Array(NUM_STARS);
  const twinkleSpeed = new Float32Array(NUM_STARS);

  function rand(a, b) { return a + Math.random() * (b - a); }

  // Build stars distributed along logarithmic spiral arms
  for (let i = 0; i < NUM_STARS; i++) {
    // Radius: denser toward the center (power distribution)
    const t = Math.pow(Math.random(), 1.6);
    const r = CORE_RADIUS + t * (GALAXY_RADIUS - CORE_RADIUS);

    // Base spiral angle at this radius
    const spiral = Math.log(r / CORE_RADIUS + 1) * ARM_TWIST;

    // Pick an arm, then scatter around it (scatter grows with radius)
    const arm = Math.floor(Math.random() * NUM_ARMS) * (Math.PI * 2 / NUM_ARMS);
    const scatter = (Math.random() - 0.5) * (0.5 + r / GALAXY_RADIUS * 1.1);
    const angle = spiral + arm + scatter;

    baseRadius[i] = r;
    baseAngle[i] = angle;

    // Size: mostly tiny, a few brighter stars
    size[i] = Math.random() < 0.06 ? rand(1.6, 2.6) : rand(0.4, 1.4);

    // Color: inner stars warm (yellow-white), outer stars cool (blue-white)
    const warmth = 1 - Math.min(1, (r - CORE_RADIUS) / (GALAXY_RADIUS - CORE_RADIUS));
    const jitter = Math.random() * 0.35;
    colorR[i] = Math.round(200 + warmth * 55 + jitter * 40);
    colorG[i] = Math.round(200 + warmth * 25 + jitter * 30);
    colorB[i] = Math.round(215 + (1 - warmth) * 40);
    colorR[i] = Math.min(255, colorR[i]);
    colorG[i] = Math.min(255, colorG[i]);
    colorB[i] = Math.min(255, colorB[i]);

    twinklePhase[i] = Math.random() * Math.PI * 2;
    twinkleSpeed[i] = rand(0.8, 3.0);
  }

  // ---- Background dust: faint static specks ----
  const NUM_DUST = 250;
  const dust = [];
  for (let i = 0; i < NUM_DUST; i++) {
    dust.push({
      x: Math.random() * W,
      y: Math.random() * H,
      s: Math.random() * 0.9 + 0.2,
      a: Math.random() * 0.35 + 0.05
    });
  }

  // ---- Pre-render the glowing core to an offscreen canvas ----
  const coreCanvas = document.createElement('canvas');
  const CORE_SIZE = 260;
  coreCanvas.width = coreCanvas.height = CORE_SIZE;
  (function() {
    const c = coreCanvas.getContext('2d');
    const half = CORE_SIZE / 2;
    const grad = c.createRadialGradient(half, half, 0, half, half, half);
    grad.addColorStop(0.00, 'rgba(255, 250, 235, 1)');
    grad.addColorStop(0.08, 'rgba(255, 240, 200, 0.9)');
    grad.addColorStop(0.25, 'rgba(255, 215, 150, 0.35)');
    grad.addColorStop(0.55, 'rgba(200, 170, 130, 0.10)');
    grad.addColorStop(1.00, 'rgba(120, 110, 120, 0)');
    c.fillStyle = grad;
    c.fillRect(0, 0, CORE_SIZE, CORE_SIZE);
  })();

  // ---- Animation loop ----
  let lastTime = performance.now();

  function frame(now) {
    const dt = Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;
    const time = now / 1000;

    // Clear with slight alpha trail for subtle motion blur
    ctx.fillStyle = 'rgba(0, 0, 0, 0.55)';
    ctx.fillRect(0, 0, W, H);

    // Draw background dust
    for (let i = 0; i < NUM_DUST; i++) {
      const d = dust[i];
      ctx.fillStyle = 'rgba(200, 210, 255, ' + d.a + ')';
      ctx.fillRect(d.x, d.y, d.s, d.s);
    }

    // Draw the core (gentle pulse)
    const pulse = 1 + Math.sin(time * 0.7) * 0.05;
    const coreDrawSize = CORE_SIZE * pulse;
    ctx.globalCompositeOperation = 'lighter';
    ctx.drawImage(coreCanvas, cx - coreDrawSize / 2, cy - coreDrawSize / 2, coreDrawSize, coreDrawSize);

    // Draw stars
    for (let i = 0; i < NUM_STARS; i++) {
      // Differential rotation: inner stars orbit faster (flat-ish curve outward)
      const omega = 0.35 / (0.35 + baseRadius[i] / GALAXY_RADIUS);
      const angle = baseAngle[i] + time * omega * 0.4;
      const r = baseRadius[i];

      const x = cx + Math.cos(angle) * r;
      const y = cy + Math.sin(angle) * r * 0.62; // slight tilt for depth

      // Twinkle
      const tw = 0.65 + 0.35 * Math.sin(time * twinkleSpeed[i] + twinklePhase[i]);

      ctx.fillStyle = 'rgba(' + colorR[i] + ',' + colorG[i] + ',' + colorB[i] + ',' + tw.toFixed(3) + ')';
      ctx.beginPath();
      ctx.arc(x, y, size[i], 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.globalCompositeOperation = 'source-over';
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
```

**How it works:**

- **Spiral structure** — Each star is assigned a radius and an angle computed from a logarithmic spiral formula (`log(r) * twist`), with 2 arms and random scatter that widens toward the edges, producing a realistic two-armed spiral pattern.
- **Differential rotation** — Inner stars orbit faster than outer ones (`omega` falls off with radius), so the spiral slowly winds over time, just like a real galaxy.
- **Color variation** — Stars interpolate from warm yellow-white near the core to cool blue-white at the rim, with per-star jitter.
- **Twinkle** — Each star oscillates its alpha with its own phase and speed.
- **Glowing core** — A pre-rendered radial gradient sprite is drawn with `globalCompositeOperation = 'lighter'` and a gentle pulse, giving a bright additive glow without per-frame gradient cost.
- **Motion blur trail** — The frame is cleared with translucent black (`rgba(0,0,0,0.55)`), leaving faint trails as stars sweep around.
- **Depth tilt** — The vertical radius is squashed (×0.62) to give the galaxy a tilted, elliptical perspective.
- **Resize handling** — The canvas adapts to window size; the galaxy radius is derived from the viewport.

Just save it as an `.html` file and open it in any browser.
